### Python

```python
import sys


# 计算单组测试数据的答案
def min_k_prefix_length(n, k, s):
    # 记录所有字符 '1' 的下标
    pos = []
    for i, ch in enumerate(s):
        if ch == '1':
            pos.append(i)

    m = len(pos)

    # 如果整个环中都不足 k 个 '1'，则无论怎么旋转都不可能满足要求
    if m < k:
        return -1

    # 把位置数组复制一份，第二份全部加上 n
    # 这样就把环形问题转化成了线性问题
    ext = pos + [x + n for x in pos]

    ans = n + 1

    # 枚举每个 '1' 作为区间起点
    # 终点取它后面的第 k 个 '1'（下标是 i + k - 1）
    for i in range(m):
        length = ext[i + k - 1] - ext[i] + 1
        if length < ans:
            ans = length

    return ans


def main():
    input = sys.stdin.readline
    t = int(input().strip())
    out = []

    for _ in range(t):
        n, k = map(int, input().split())
        s = input().strip()
        out.append(str(min_k_prefix_length(n, k, s)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Main {

    // 计算单组测试数据的答案
    public static int minKPrefixLength(int n, int k, String s) {
        // 记录所有字符 '1' 的下标
        ArrayList<Integer> posList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                posList.add(i);
            }
        }

        int m = posList.size();

        // 如果总共不足 k 个 '1'，则答案为 -1
        if (m < k) {
            return -1;
        }

        // 构造扩展数组，把环展开成链
        int[] ext = new int[m * 2];
        for (int i = 0; i < m; i++) {
            ext[i] = posList.get(i);
            ext[i + m] = posList.get(i) + n;
        }

        int ans = n + 1;

        // 枚举连续的 k 个 '1'
        for (int i = 0; i < m; i++) {
            int length = ext[i + k - 1] - ext[i] + 1;
            if (length < ans) {
                ans = length;
            }
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());

        for (int caseId = 0; caseId < T; caseId++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            String s = br.readLine().trim();

            sb.append(minKPrefixLength(n, k, s)).append('\n');
        }

        System.out.print(sb.toString());
    }
}
